<template><div><div class="page-head"><div><h1>Inventory Report</h1><p>Stock value, retail value and replenishment priorities.</p></div><RouterLink to="/products" class="btn btn-primary">Manage products</RouterLink></div><div class="grid grid-cols-1 gap-3 sm:grid-cols-3"><div class="card metric"><div class="metric-label">Stock cost value</div><div class="metric-value mt-2">{{money(data.stock_value)}}</div></div><div class="card metric"><div class="metric-label">Retail value</div><div class="metric-value mt-2">{{money(data.retail_value)}}</div></div><div class="card metric"><div class="metric-label">Low stock</div><div class="metric-value mt-2">{{data.low_stock?.length||0}}</div></div></div><div class="card mt-4 overflow-hidden"><table class="data-table"><thead><tr><th>Product</th><th>SKU</th><th>Stock</th><th>Minimum</th><th>Cost value</th><th>Status</th></tr></thead><tbody><tr v-for="p in data.products||[]" :key="p.id"><td>{{p.name}}</td><td>{{p.sku}}</td><td>{{p.stock_quantity}}</td><td>{{p.minimum_stock}}</td><td>{{money(Number(p.stock_quantity)*Number(p.cost_price))}}</td><td><span class="status" :class="Number(p.stock_quantity)<=Number(p.minimum_stock)?'status-warning':'status-success'">{{Number(p.stock_quantity)<=Number(p.minimum_stock)?'Low':'Healthy'}}</span></td></tr></tbody></table></div></div></template>
<script setup lang="ts">import {onMounted,ref} from 'vue';import {api} from '../../services/api';const data=ref<any>({products:[],low_stock:[]});function money(v:any){return new Intl.NumberFormat('en-TZ',{style:'currency',currency:'TZS',maximumFractionDigits:0}).format(Number(v||0))}async function load(){data.value=(await api.get('/reports/inventory')).data}onMounted(load)</script>
